ntp_pools.description:
List of additional NTP pools to include for redundancy.
      items:
        type: object
        fields:
          name: { type: string, default: '', description: 'Descriptive name for the pool (e.g., "Regional Pool").' }
          hostname: { type: string, default: '', description: 'Hostname or FQDN of the NTP pool (e.g., "0.pool.ntp.org").' }
          description: { type: string, default: '', description: 'Brief description of the pool purpose or region.' }
